import { get } from 'lodash'

export function objectTypeHandler (type, state, currentStateId) {
  const stateData = get(state, 'data', [])
  let originalData = stateData
  originalData = originalData.filter(item => item.id <= currentStateId)

  originalData = originalData.map((item) => {
    if (item.id === currentStateId) {
      return {
        ...item,
        buttonType: type
      }
    } else {
      return item
    }
  })
  originalData = originalData.map((item) => {
    if (item.buttonType === 'object' && item.parent_id) {
      return {
        ...item,
        tableShow: true
      }
    } else if (item.buttonType === 'regular' && item.parent_id) {
      return {
        ...item,
        tableShow: false,
        tableData: []
      }
    } else {
      return item
    }
  })
  return originalData
}
