import { useEffect, useState, useRef } from 'react'
import { Row, Col } from 'antd'
import { get } from 'lodash'
import { ProviderDetailContextProvider } from '../context'
import { StateProvider } from '../context/attributeContext'
import Screen2 from '../pages/Screen2'
import { attributeMapper } from './attributeMapper'
import StyleWrapper from './index.style'

export default function EditScreen2Data ({ ...props }) {
  const { step2, functionName, provider, productCode, packageCode } = get(props, 'location.state', {})
  const [intialValueAttributes, setAttributes] = useState([])
  const that = useRef({
    isCall: false
  })
  useEffect(() => {
    if (!that.current.isCall) {
      const data = {
        ...get(props, 'location.state', {})
      }
      const tableData = get(data, 'providerAttributeData').length === 0 ? attributeMapper([]) : attributeMapper([get(data, 'providerAttributeData')])
      setAttributes(tableData)
      that.current.isCall = true
    }
  }, [props])

  return (
    <StyleWrapper>
      <ProviderDetailContextProvider>
        <StateProvider>
          <Row type='flex' justify='center'>
            <Col span={22}>
              <Screen2
                type='edit'
                initialValue={intialValueAttributes}
                step2={step2}
                history={props.history}
                functionName={functionName}
                provider={provider}
                productCode={productCode}
                packageCode={packageCode}
              />
            </Col>
          </Row>
        </StateProvider>
      </ProviderDetailContextProvider>
    </StyleWrapper>
  )
}
