
export function attributeMapper (data) {
  if (data.length === 0) {
    return [{
      id: 1,
      fieldType: 'enabled',
      provider_attribute_id: null,
      buttonType: 'regular',
      parent_id: null,
      product_attribute_id: null,
      is_array: false,
      prefix: '',
      suffix: '',
      convert_value_to_string: false,
      formatting: '',
      showAddButton: false,
      showDeleteButton: false,
      tableShow: false,
      fallback_product_attribute_id: null,
      fallback_type: null,
      fallback_static_value: '',
      status: 'active',
      convert_value_to_numeric: false,
      tableData: []
    }]
  }
  const tableData = []
  const firstData = {
    ...data[0],
    id: 1,
    fieldType: 'disabled',
    buttonType: data[0].datatype === 'object' ? 'object' : 'regular',
    showAddButton: false,
    showDeleteButton: false,
    tableShow: false,
    tableData: []
  }
  tableData.push(firstData)
  if (data[0].children && data[0].children.length > 0) {
    tableData.push(...childExtractor(data[0].children, data[0].children.length, 1))
  }
  return tableData
}

function childExtractor (children, length, globalIndex) {
  function traverse (data) {
    return data.map((item, index) => {
      return {
        ...item,
        id: globalIndex + 1,
        fieldType: 'disabled',
        buttonType: item.datatype === 'object' ? 'object' : 'regular',
        showAddButton: (length - index === 1),
        showDeleteButton: false,
        tableShow: Boolean(item.children && item.children.length > 0),
        tableData: item.children && item.children.length > 0 ? traverse(item.children) : []
      }
    })
  }
  return traverse(children)
}
